class PriceChart {
  points = Array.from({ length: 100_000 }, () => Math.random());

  constructor(container) {
    this.el = document.createElement("canvas");
    container.append(this.el);
    window.addEventListener("resize", () => this.redraw());
  }

  redraw() {
    console.log(`redraw ${this.points.length} points`);
  }

  destroy() {
    this.el.remove(); // the canvas leaves the page, the listener stays
  }
}

const app = document.querySelector("#app");
for (let i = 0; i < 200; i++) new PriceChart(app).destroy();

class PriceChart {
  points = Array.from({ length: 100_000 }, () => Math.random());
  #listeners = new AbortController();

  constructor(container) {
    this.el = document.createElement("canvas");
    container.append(this.el);
    window.addEventListener("resize", () => this.redraw(), {
      signal: this.#listeners.signal,
    });
  }

  redraw() {
    console.log(`redraw ${this.points.length} points`);
  }

  destroy() {
    this.el.remove();
    this.#listeners.abort(); // removes every listener added with this signal
  }
}

const app = document.querySelector("#app");
for (let i = 0; i < 200; i++) new PriceChart(app).destroy();

